node --version && node -e '
import("./src/server.mjs").then(async m => {
  const a = m.handleUpload({x:1}, "r1", 0);
  const b = m.handleUpload({x:1}, "r1", 0);
  console.log("same-key twice:", JSON.stringify(a), JSON.stringify(b));
  console.log("health:", JSON.stringify(m.health()));
  // does anything delete after 24h?
  const c = m.handleUpload({x:2}, "r2", 0);
  console.log("no exported delete/sweep:", Object.keys(m));
  // client retry behavior
  const cl = await import("./src/client.mjs");
  let calls = 0;
  const fetcher = async () => { calls++; if (calls === 1) throw new Error("timeout"); return {ok:true, call:calls}; };
  console.log("client retry:", JSON.stringify(await cl.upload(fetcher, {x:1}, "r1")), "calls:", calls);
  let c2 = 0;
  const f2 = async () => { c2++; throw new Error("connection refused"); };
  try { await cl.upload(f2, {x:1}, "r1"); } catch (e) { console.log("non-timeout error retried too, calls:", c2, "then threw:", e.message); }
});'

